1	/**
2	 * Global feature flag hook — used throughout the app (not admin-only).
3	 * Reads from the same system_config table as the admin feature flags.
4	 * Has a longer staleTime (5 min) since feature flags change rarely.
5	 */
6	
7	import { useQuery } from "@tanstack/react-query";
8	import supabase from "@/lib/supabase";
9	import { FLAG_DEFINITIONS } from "@/hooks/admin/use-feature-flags";
10	
11	const DEFAULT_FLAGS: Record<string, boolean> = Object.fromEntries(
12	  FLAG_DEFINITIONS.map((f) => [f.key, f.defaultValue])
13	);
14	
15	async function fetchAllFeatureFlags(): Promise<Record<string, boolean>> {
16	  const { data, error } = await supabase
17	    .from("system_config")
18	    .select("value")
19	    .eq("key", "feature_flags")
20	    .single();
21	
22	  if (error && error.code !== "PGRST116") {
23	    // On error, return defaults silently — never break app for missing config
24	    return DEFAULT_FLAGS;
25	  }
26	
27	  const stored = (data?.value ?? {}) as Record<string, boolean>;
28	  return { ...DEFAULT_FLAGS, ...stored };
29	}
30	
31	/**
32	 * Returns the boolean value of a single feature flag.
33	 * Falls back to `defaultValue` if the flag is not set or loading.
34	 */
35	export function useFeatureFlag(key: string, defaultValue = true): boolean {
36	  const { data } = useQuery({
37	    queryKey: ["feature-flags"],
38	    queryFn: fetchAllFeatureFlags,
39	    staleTime: 5 * 60 * 1000, // 5 minutes
40	    // Never throw on error — silently use defaults
41	    retry: 1,
42	  });
43	
44	  if (data === undefined) {
45	    // Still loading — return the flag's defined default or the passed default
46	    const flagDef = FLAG_DEFINITIONS.find((f) => f.key === key);
47	    return flagDef?.defaultValue ?? defaultValue;
48	  }
49	
50	  return data[key] ?? defaultValue;
51	}
